// WF1 — normalise n'importe quel formulaire de landing page vers le contrat
// attendu par POST /api/webhooks/leads/inbound du CRM.
// Le corps signé DOIT être exactement le corps envoyé -> on sérialise ici une
// seule fois dans `payload`, la signature et la requête HTTP réutilisent cette
// même chaîne.

const ACTIVITIES = ['urgence', 'nettoyage', 'enr', 'renovation', 'debarras', 'demenagement'];
const SOURCES = ['google_ads', 'meta_ads', 'site_web', 'telephone', 'recommandation'];

// Alias tolérés pour la source (les LP envoient rarement le slug exact).
const SRC_ALIAS = {
  google: 'google_ads', 'google-ads': 'google_ads', googleads: 'google_ads', adwords: 'google_ads',
  facebook: 'meta_ads', meta: 'meta_ads', instagram: 'meta_ads', fb: 'meta_ads',
  site: 'site_web', web: 'site_web', website: 'site_web', formulaire: 'site_web',
  phone: 'telephone', tel: 'telephone',
  reco: 'recommandation', parrainage: 'recommandation',
};

// Secteur par défaut si la LP n'envoie rien d'exploitable. À adapter par LP.
const DEFAULT_ACTIVITY = 'nettoyage';
const DEFAULT_SOURCE = 'site_web';

const out = [];

for (const item of $input.all()) {
  // Le noeud Webhook range le corps du POST sous .body (form-data ou JSON).
  const b = item.json.body || item.json.query || item.json || {};

  const pick = (...keys) => {
    for (const k of keys) {
      const v = b[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };
  const truthy = (s) => ['true', '1', 'oui', 'yes', 'on'].includes(s.toLowerCase());

  // Téléphone -> E.164 (le CRM refuse un lead sans téléphone).
  let phone = pick('phone', 'telephone', 'tel', 'mobile', 'numero').replace(/[^\d+]/g, '');
  if (/^0\d{9}$/.test(phone)) phone = '+33' + phone.slice(1);

  let activity = pick('activity_slug', 'activity', 'prestation', 'service', 'metier').toLowerCase();
  if (!ACTIVITIES.includes(activity)) activity = DEFAULT_ACTIVITY;

  let source = pick('source_slug', 'source', 'utm_source').toLowerCase();
  source = SRC_ALIAS[source] || source;
  if (!SOURCES.includes(source)) source = DEFAULT_SOURCE;

  const isCompany = truthy(pick('is_company', 'societe', 'pro'));
  const num = (s) => { const n = Number(String(s).replace(',', '.')); return Number.isFinite(n) && n > 0 ? n : null; };

  // Nom complet dans un seul champ ("Jean Dupont") -> split prénom/nom.
  let firstName = pick('first_name', 'prenom', 'firstname', 'fname');
  let lastName = pick('last_name', 'nom', 'lastname', 'lname');
  if (!firstName && lastName.includes(' ')) {
    const nameParts = lastName.split(/\s+/);
    firstName = nameParts.shift();
    lastName = nameParts.join(' ');
  }

  // Surface : accepte un nombre OU un libellé de tranche ("50 à 100 m²",
  // "Plus de 100 m²") -> on extrait le premier entier trouvé pour que la
  // règle de routing "superficie > 80" fonctionne quand même.
  const surfaceMatch = pick('surface_m2', 'surface', 'm2', 'superficie').match(/\d+/);
  const surfaceM2 = surfaceMatch ? num(surfaceMatch[0]) : null;

  const lead = {
    // Clé d'idempotence : le CRM ne créera pas deux fois le même lead.
    external_id: pick('external_id') || `lp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    is_company: isCompany,
    first_name: firstName,
    last_name: lastName,
    company_name: pick('company_name', 'societe_nom', 'company', 'entreprise') || null,
    email: pick('email', 'mail', 'e-mail').toLowerCase(),
    phone: phone,
    address_line: pick('address_line', 'adresse', 'address', 'rue'),
    postal_code: pick('postal_code', 'code_postal', 'cp', 'zip'),
    city: pick('city', 'ville'),
    activity_slug: activity,
    source_slug: source,
    estimated_amount: num(pick('estimated_amount', 'budget', 'montant')),
    surface_m2: surfaceM2,
    type_service: pick('type_service', 'service_type', 'type_prestation', 'formule') || null,
    is_extreme: truthy(pick('is_extreme', 'urgent', 'urgence_extreme')),
    gclid: pick('gclid') || null,
    utm_source: pick('utm_source') || null,
    utm_campaign: pick('utm_campaign') || null,
    utm_medium: pick('utm_medium') || null,
    utm_term: pick('utm_term') || null,
    utm_content: pick('utm_content') || null,
    notes: pick('notes', 'message', 'commentaire', 'demande', 'description'),
  };

  // Garde-fous : le CRM renverrait 400, autant le dire clairement ici.
  const missing = [];
  if (!lead.phone) missing.push('phone');
  if (isCompany && !lead.company_name) missing.push('company_name');
  if (!isCompany && !`${lead.first_name} ${lead.last_name}`.trim()) missing.push('nom');

  out.push({
    json: {
      payload: JSON.stringify(lead), // <- chaîne signée ET envoyée
      lead: lead,
      valid: missing.length === 0,
      missing: missing.join(', '),
    },
  });
}

return out;
